"""Build the current defense deck from final-label artifacts, preserving v12."""
import base64
import html
import json
import re
import shutil
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'results/defense_build';OUT.mkdir(exist_ok=True)
R=json.loads((ROOT/'results/demo_v13_release/report.json').read_text())
A=R['audit'];M={m['model']:m for m in R['models']}
old=ROOT/'results/defense_v12_backup';old.mkdir(exist_ok=True)
for path in [ROOT/'docs/hoca_sunumu.html',ROOT/'docs/sunum_konusma_notlari.md',OUT/'canine_sunum.pdf']:
    if path.exists() and not (old/path.name).exists():shutil.copy2(path,old/path.name)
template=(old/'hoca_sunumu.html').read_text()
css=re.search(r'<style>(.*?)</style>',template,re.S).group(1)
script=re.search(r'<script>(.*?)</script>',template,re.S).group(1)
slides=[];notes=[]
def table(headers,rows):
    return '<table><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</table>'
def add(title,body,note):
    slides.append('<section class="slide"><h1>'+html.escape(title)+'</h1>'+body+'<aside>'+html.escape(note)+'</aside></section>');notes.append((title,note))
titles=dict(hareket='Hareket',ses='Ses',durus='Duruş',kuyruk_konum='Kuyruk konumu',kuyruk_hareket='Kuyruk hareketi',kulak='Kulak')
add('Son etiketlerle çok modlu analiz','<p class="lead">Poz ve ses temsillerinden altı görevli davranış tahmini</p><p>Son insan etiketleriyle yeniden eğitim ve kontrollü model karşılaştırması</p><p class="muted">14 Kasım 2026 · labels_final-v13 · Nilüfer Öden</p>', 'Projede duygu hedefi var, fakat mevcut doğrulanmış insan etiketleri davranış ve ses türleridir. Yeni dosyayla altı görev yeniden eğitildi. Duygu doğruluğu iddia etmiyorum.')
add('Yeni dosya veri kapsamını değiştirdi',table(['Durum','Video'],[['Toplam / eski etiketsiz',f'{A["total"]} / {A["formerly_unlabelled"]}'],['Yeni kullanılabilir eğitim',A['newly_usable_training']],['Eğitim',A['training_videos']],['Korunan test / ölçülebilen test',f'{A["original_test_videos"]} / {A["evaluable_test_videos"]}'],['Güvensiz / zamanla değişken',f'{A["unsafe"]} / {A["variable_videos"]}']]),'Eski 25 test dosyasını eğitimden uzak tuttum. İkisi yeni dosyada güvensiz işaretli, bu nedenle 23 videoda ölçüm var. Eski etiketsizlerden 27 tanesi güvenli eğitim verisi oldu. Etiketlerin boş olması bütün videoyu çöpe atmak anlamına gelmiyor; hedef bazında maskeliyoruz.')
add('Altı bağımsız hedef',table(['Hedef','Eğitim etiketi','Test etiketi'],[[titles[t],A['per_target'][t]['training'],A['per_target'][t]['test']] for t in R['targets']]),'Vücut etiketi kaldırıldı. Hareket ve ses ayrı hedef oldu. Kuyruk konumu ile kuyruk hareketi ayrıldı. Uzlaşılmayan, görünmeyen ve boş hücreler yalnız ilgili hedefte eğitim ve ölçüm dışında.')
add('Derin öğrenmede eğitilen bölüm','<p>Görüntü: YOLOv8n → RTMPose-S → 471 poz/hareket özelliği</p><p>Ses: YAMNet → 1024 temsil + 29 olay özelliği</p><p>FusionNet: iki öğrenilebilir özellik dalı → birleşim → altı sınıflandırma başlığı</p><p class="muted">Ön-eğitimli kodlayıcılar donmuş. Piksel ve dalga biçiminden uçtan uca ince ayar yapılmadı.</p>', 'Hazır kodlayıcıları kullanmakla yetinmedik; yeni etiketlerle çok görevli sinir ağının tahmin başlıklarını eğittik. Sinir ağı çıktılarında vücut artık yok. Yeni video çıkarımı da kontrol noktasındaki altı hedef sırasını okuyor.')
add('Seçim ve test protokolü','<p>Eğitim içinde üç katlı GroupKFold; grup: kaynak dosya SHA256</p><p>20 / 40 / 60 / 80 epoch yalnız eğitim CV ile seçildi.</p><p>Ölçekleme, sınıf ağırlıkları ve model seçimi eğitim verisine dayanır.</p><p class="muted">Test daha önce incelendi. Aynı köpeğin farklı kayıtlarda olması dışlanamadı. Sonuçlar keşifseldir.</p>', 'Test performansına bakıp kazanan mimari seçmedik. Tüm seçimleri test skorlarını hesaplamadan kaydettik. Fakat daha önce incelenmiş test dosyaları bağımsız yeni doğrulama değildir. Kalite ve etiket notlarını model girdisi olarak kullanmadık.')
add('Sinir ağlarında modalite karşılaştırması',table(['Model','CV macro-F1','Test macro-F1'],[[name,f'{R["selection"]["models"][key]["cv_macro_f1"]:.3f}',f'{M[key]["mean_test_macro_f1"]:.3f}'] for key,name in [('neural_visual','Görüntü'),('neural_audio','Ses'),('neural_fusion','Görüntü + ses')]])+'<p class="muted">Altı hedefin sabit sınıf listeleri üzerinden macro-F1 ortalaması. Doğruluk yüzdesi değildir.</p>','Yeni etiketlerle görüntü modeli 0,449, ses modeli 0,368 ve birleşik model 0,442 aldı. Birleşim bu testte görüntüyü geçmedi. Eski beş hedefli sonuçla artış hesabı yapılmaz; görev tanımı değişti.')
add('Zamansal mimariler ve makale uyarlaması',table(['Mimari','CV macro-F1','Test macro-F1'],[[name,f'{R["selection"]["models"][key]["cv_macro_f1"]:.3f}',f'{M[key]["mean_test_macro_f1"]:.3f}'] for key,name in [('sequence_cnn','CNN1D'),('sequence_gru','GRU'),('sequence_bigru','BiGRU'),('sequence_lstm_lstm_gru','LSTM → LSTM → GRU')]])+'<p class="muted">Aynı 1 Hz poz + YAMNet dizileri. Hibrit fikir: DOI 10.3389/fvets.2026.1799281; birebir tekrar değil.</p>','Zamansal modelleri aynı dizi girdisiyle kıyasladık. Makalenin MFCC ses girdisi yerine mevcut poz ve YAMNet dizileri kullanıldı. Bütün katmanlar 32 birim; özgün modelin genişlikleriyle aynı değil. Makalenin yüzde 95 sonucunu burada elde ettik demiyoruz.')
add('Klasik referanslar hâlâ gerekli',table(['Referans','Test macro-F1'],[[name,f'{M[key]["mean_test_macro_f1"]:.3f}'] for key,name in [('classical_visual','Klasik görüntü'),('classical_audio','Klasik ses'),('classical_fusion','Klasik birleşik'),('majority_baseline','Çoğunluk tahmini')]])+'<p class="muted">LR / RF seçimi eğitim CV ile. Genel CV seçimi klasik birleşik modeldir; testteki en yüksek skora göre değiştirilmedi.</p>','Küçük veride klasik referansı göstermek önemlidir. Testte görüntü referansı daha yüksek olsa da eğitim CV seçimi birleşik modeldi. Uygulamada CV ile seçilen klasik birleşik model öne çıkarılır; sinir ağları karşılaştırılabilir kalır.')
add('Birleşik sinir ağının hedef sonuçları',table(['Hedef','Macro-F1','Doğru oranı','Test n'],[[titles[m['target']],f'{m["macro_f1"]:.3f}',f'{m["accuracy"]:.1%}',m['support']] for m in M['neural_fusion']['metrics']]),'Ortalama skor tek başına yeterli değil. Kulak yalnız 14 test videosuyla, kuyruk konumu 17 videoyla değerlendiriliyor. Her hedefin desteğini birlikte gösteriyorum. Sabit sınıf listelerinde testte olmayan sınıflar da macro-F1 ortalamasına sıfır katkı yapar.')
add('Veri sınırları sonuçları etkiliyor','<p>Eğitimde hırlama 1; oturma ve sırtüstü 2’şer kayıt.</p><p>Çoklu köpekte büyük kutu ile insanın odak köpeği eşleşmeyebilir.</p><p>Odak köpek sessizken arka planda havlama duyulabilir.</p><p class="muted">Yeni kimlikler, birey odak kutuları ve bağımsız kayıtlarla ölçüm gerekli.</p>', 'Nadir sınıflarda güvenilir başarı iddia etmiyoruz. Tek bir hırlama eğitim örneği farklı köpeklere genelleme sağlamaz. Kalıcı takip ve odak köpek etiketleme önemli açıklar. Birleşimde ses eklemenin her hedefi iyileştirmesi beklenmemeli.')
add('Çalışan uygulama ve segmentasyon','<p>127 videolu galeri: son gerçek etiket, kalite bayrağı, 11 model/referans</p><p>Yeni video: altı hedef, model karşılaştırması, YAMNet ses zamanları</p><p>YOLOv8s-seg: gerçek piksel maskeleri, video, ayrı PNG ve JSON</p><p class="muted">Maske doğruluğu ölçülmedi. Segmentasyon özellikleri davranış eğitimine katılmadı. Anlık davranış doğruluğu ölçülmedi.</p>', 'Galeri eski etiketleri göstermiyor. Yeni video yükleme de yeni kontrol noktalarını kullanıyor. Geçmiş analizler kendi eski sürüm bilgileriyle saklanır ve yeni etiket sürümünün sonuçları gibi sunulmaz. Segmentasyon gerçek model çıktısı, fakat IoU veya Dice ölçümü için insan maskeleri yok.')
add('Sunulabilecek sonuç ve sonraki deney','<p class="lead">Son insan etiketleriyle altı görevli, yeniden eğitilmiş ve karşılaştırılmış bir prototip</p><p>Eksik hedeflerde maskeleme; korunmuş test üyeliği; eğitim içi seçim</p><p>Öncelik: odak köpek kimliği ve zaman etiketleri, nadir sınıflar, bağımsız yeni kayıtlar</p><p class="muted">Davranış/ses tahmini tamamlandı; doğrulanmış duygu sınıflandırması için uygun duygu etiketleri hâlâ gerekli.</p>', 'Bu aşamada katkı, veri kapsamını tamamlamak ve yeni şemayı bütün eğitim/çıkarım akışına taşımaktır. Veri ve duygu doğrulaması açıklarını gizlemiyoruz. Bu sürümde yeni test grubu icat edilmedi ve önceki test eğitime katılmadı.')
day_path=ROOT/'results/day_validation_v14/report.json'
if day_path.exists():
    day=json.loads(day_path.read_text());last_slide,last_note=slides.pop(),notes.pop()
    add('V14: çekim gününü dışarıda bırakmak',table(['Metadata / güvenli veri','Kapsam'],[['Kamera creationdate bilgisi','114 video'],['Güvenli, kamera tarihi bilinen','103 video'],['Kamera günü dağılımı','18 Haziran: 60 / 20 Haziran: 4 / 22 Haziran: 39'],['Dış kat / iç kat','Günü dışarıda tut / kalan günlerle seçim']])+'<p class="muted">Metadata günü onaylanmış oturum veya köpek kimliği değildir. Yalnız container tarihli 9 ve tarihsiz 4 kayıt değerlendirme dışında.</p>','Arkadaşımızın bölme eleştirisi üzerine gün gruplu yeniden doğrulama ekledik. Kamera metadata tarihini kullandık; bazı dosyalarda container tarihi farklı. Tarihsiz videoları dosya adına göre tahminle gruplamadık. İki ham etiketleyici formu olmadığı için kappa hesaplamadık.')
    labels=dict(neural_visual='Görüntü ağı',neural_audio='Ses ağı',neural_fusion='FusionNet',sequence_cnn='CNN1D',sequence_gru='GRU',sequence_bigru='BiGRU',sequence_lstm_lstm_gru='LSTM → LSTM → GRU',classical_visual='Klasik görüntü',classical_audio='Klasik ses',classical_fusion='Klasik birleşik',majority_baseline='Çoğunluk')
    for title,group in [('Gün gruplu sinir ağı sonuçları',day['models'][:7]),('Gün gruplu klasik referanslar',day['models'][7:])]:
        add(title,table(['Model','Dış-kat macro-F1','Gün ort. macro-F1'],[[labels[m['model']],f'{m["pooled_oof_macro_f1"]:.3f}',f'{m["equal_day_mean_macro_f1"]:.3f}'] for m in group])+'<p class="muted">3 kamera günü; birinde yalnız 4 video. Geçmiş veri üzerinde yeniden doğrulama; yeni bağımsız test değildir.</p>','Her dış günde model ayarlarını yalnız kalan günlerde seçtik. İlk skor bütün dış-kat tahminlerini birleştirir, ikinci skor günlere eşit ağırlık verir. Eski 23 videolu dosya bölmesiyle doğrudan yöntem kazancı hesabı yapılmaz. Çok az gün ve örnek olduğu için genel üstünlük iddiası kurmuyoruz.')
    slides.append(last_slide);notes.append(last_note)
affect_path=ROOT/'results/affect_v15_clean/report.json'
if affect_path.exists():
    affect=json.loads(affect_path.read_text());fusion=json.loads((ROOT/'results/late_fusion_v15/report.json').read_text())
    last_slide,last_note=slides.pop(),notes.pop()
    add('V15: karar düzeyinde görüntü + ses',table(['Aynı 103 dış-kat video','Macro-F1'],[['Neural fusion','0.330'],['Klasik erken birleşim','0.346'],['Eğitimde seçilen karar birleşimi',f'{fusion["mean_macro_f1"]:.3f}']])+'<p>Canlı seçim: %75 görüntü + %25 ses kararı</p><p class="muted">Reçete yalnız 93 eğitim videosunda CV ile seçildi. Gün gruplu değerlendirme geçmiş veri üzerindedir; yeni bağımsız test değildir.</p>','Karışımı elle test skoruna bakıp ayarlamadık. Dokuz aday reçeteyi yalnız iç eğitim katlarında karşılaştırdık. Aynı günlerden gelen dış-kat skorunda keşifsel kazanç var; genel üstünlük kanıtı olarak sunmuyoruz.')
    add('İnsan algısı etiketleriyle ses duygu modeli',table(['Model','Ort. macro-F1','Duygu yönü doğruluğu','Uyarılma doğruluğu'],[[m['model'],f'{m["mean_test_macro_f1"]:.3f}',f'{m["metrics"][0]["accuracy"]:.1%}',f'{m["metrics"][1]["accuracy"]:.1%}'] for m in affect['results']])+'<p class="muted">EmotionalCanines: temiz eğitim 1.195 / resmi test 200 (199 benzersiz ses). Eğitim CV seçimi RF. İki boyut birlikte doğru: %23,5. Yalnız Husky/Shiba, insan algısı etiketleri.</p>','Yeni başlık bizim davranış kurallarımızdan etiket almadı. Yazarların arousal/valence insan etiketlerini kullandık. İki ortak eğitim/test sesi, çelişkili ve tekrarlı eğitim kaydı karantinaya alındı. Testteki 200 satır korundu. İki ırk birlikte eğitildi; makalenin birebir tekrarı değil. Yerel 127 videoda duygu başarısı ölçülmedi.')
    add('Yeni videoda tek ana değerlendirme','<p class="lead">Tahmini: Olumlu · yüksek uyarılma</p><p>Gerçek havlamalı video denemesi · Destek: sınırlı</p><p>Önerilen davranış sonucu ve diğer modeller ayrı kanıt olarak gösterilir.</p><p class="muted">Bu ses modelinin insan algısı sınıflarıdır. Korku/öfke ayrımı eğitilmedi. Ses yoksa duygu uydurulmaz. Çoklu köpekte ses belirli bir bireye atanmaz.</p>','Arayüz artık tek bir ana sonuç gösteriyor ama kesinlik uydurmuyor. Bu örnekte destek sınırlı. Ses sınıflandırıcısı görüntüden duygu öğrenmedi; senkron çok modlu duygu eğitimi için uygun insan etiketlerine ihtiyacımız sürüyor. Model puanları kalibre olasılık veya doğruluk yüzdesi değildir.')
    slides.append(last_slide);notes.append(last_note)
output=ROOT/'docs/hoca_sunumu.html'
output.write_text('<!doctype html><html lang="tr"><meta charset="utf-8"><title>Canine · Son etiket sunumu</title><style>'+css+'</style>'+''.join(slides)+'<nav><span>← → slayt · N notlar · F tam ekran</span><span><button id="prev">Önceki</button> <span id="count"></span> <button id="next">Sonraki</button> <button id="notes">Notlar</button></span></nav><script>'+script+'</script></html>')
(ROOT/'docs/sunum_konusma_notlari.md').write_text('# Son etiketlerle sunum notları · v13\n\n'+'\n\n'.join(f'## {i}. {title}\n\n{note}' for i,(title,note) in enumerate(notes,1))+'\n')
print('Built',len(slides),'final-label slides')
